import http from 'node:http';
import pg from 'pg';

const { Pool } = pg;
const pool = new Pool({
  connectionString: process.env.DATABASE_URL ?? 'postgres://postgres:postgres@127.0.0.1:55432/contract_study'
});
const port = Number(process.env.PORT ?? 3000);

const json = (response, status, body) => {
  response.writeHead(status, { 'content-type': 'application/json' });
  response.end(JSON.stringify(body));
};
const requestPath = (request) => new URL(request.url ?? '/', 'http://127.0.0.1').pathname;

const server = http.createServer(async (request, response) => {
  try {
    if (request.method === 'GET' && requestPath(request) === '/health') {
      await pool.query('select 1');
      return json(response, 200, { status: 'ok' });
    }
    // The application surface is intentionally small. Unknown endpoints remain inert.
    return json(response, 404, { error: 'not found' });
  } catch (error) {
    return json(response, 500, { error: error instanceof Error ? error.message : String(error) });
  }
});

server.listen(port, '127.0.0.1');
const shutdown = async () => { await pool.end(); server.close(); };
process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);

# Raw SQL contract study fixture

This is a small Node.js application backed by PostgreSQL and `node-postgres`.
The database is initialized from `database/init.sql`; the application listens
on `PORT` and uses `DATABASE_URL`.

Run it locally with Docker and npm:

```sh
docker compose up -d postgres
npm install
DATABASE_URL=postgres://postgres:postgres@127.0.0.1:55432/contract_study PORT=3000 npm start
```

On PowerShell, set the two environment variables before `npm start`. Stop the
database with `docker compose down --volumes` after a run. The source is kept
deliberately small and does not require a web framework.

services:
  postgres:
    image: postgres:16-alpine
    environment:
      POSTGRES_USER: postgres
      POSTGRES_PASSWORD: postgres
      POSTGRES_DB: contract_study
    ports:
      - "${POSTGRES_PORT:-55432}:5432"
    volumes:
      - ./database/init.sql:/docker-entrypoint-initdb.d/001-init.sql:ro


